        if(rw){ const aw=inRC&&x.px!=null&&((x.x-x.px)*(x.x-u.x)+(x.y-x.py)*(x.y-u.y))>1e-9, ha=!!A.markOf(u,x,'rcA'); if(aw&&!ha) A.setMark(T,u,x,'rcA',{}); else if(!aw&&ha) A.clearMark(u,x,'rcA'); }
