          if(!s.odT&&x._debtOwner===u&&Math.abs(d.dps-(x._debtDps||0)*(x._debtStk||0))<=1e-9*Math.max(1,d.dps)){ s.odT=x; T.fn.notice(A,T,u,x,d,mx,c,k0); }
