    lh_4_1:[ {on:'teamIn',if:{srcHas:'listen',targetTeam:'enemy'},more:R(0.01)} ],                  // Rapt Crowd
    lh_8_3:[ {param:'pp.on',add:1}, {param:'pp.dur',add:R(0.4)} ],                                  // Bright Timbre
