    if(a.buff){ const k=a.buff, x=amtOf(T,u,a.x,ctx), d=amtOf(T,u,a.dur,ctx); if(!(d>0)) return; for(const t of pick(T,u,a.on||'self',ctx)) if(t.alive) buffOn(t,k,x,d); return; }   // one of the engine's own timed buffs (see buffOn)
